"""Records the audio samples of the CreateListener wiki page: a 440 Hz tone that flies past the listener, played through SDL's disk
audio driver, as mono 16 bit files of 11025 Hz.

Usage: render_doppler_samples.py <blitzcc> <output folder>
"""
import os
import struct
import subprocess
import sys
import tempfile
import wave

blitzcc, out_dir = (os.path.abspath(a) for a in sys.argv[1:3])
os.makedirs(out_dir, exist_ok=True)
work = tempfile.mkdtemp()
os.chdir(work)

CYCLE, RATE = 50, 22050
with wave.open("tone.wav", "wb") as f:
	f.setnchannels(1)
	f.setsampwidth(2)
	f.setframerate(RATE)
	f.writeframes(b"".join(struct.pack("<h", int(9000 * __import__("math").sin(2 * 3.141592653589793 * i / CYCLE))) for i in range(CYCLE * 40)))

SOURCE = """
s = Load3DSound("tone.wav")
LoopSound s
listener = CreatePivot()
source = CreatePivot()
PositionEntity source, 0, 0, %f
CreateListener listener, 1, %f, %f
c = EmitSound(s, source)
For i = 1 To 40
	MoveEntity source, 0, 0, -3.0
	Delay 50
Next
"""


def record(name, scale, distance):
	# The source starts 60 units in front of the listener and passes it at 3 units every 50 ms.
	with open("play.bb", "w") as f:
		f.write(SOURCE % (60.0, scale, distance))
	subprocess.run([blitzcc, "play.bb", "-o", "play"], check=True, capture_output=True)
	if os.path.exists("sdlaudio.raw"):
		os.remove("sdlaudio.raw")
	env = dict(os.environ, SDL_AUDIODRIVER="disk", SDL_DISKAUDIODELAY="0")
	env.pop("BLITZ_HEADLESS", None)
	subprocess.run(["./play"], env=env, capture_output=True, timeout=60)
	data = open("sdlaudio.raw", "rb").read()
	count = len(data) // 4
	left = struct.unpack("<%dh" % (count * 2), data[: count * 4])[0::2]
	# From the first sound to the last one, 44100 Hz down to 11025 Hz by taking every fourth sample (the tone is low).
	loud = [i for i, v in enumerate(left) if abs(v) > 100]
	chosen = left[loud[0] : loud[-1] + 1 : 4]
	with wave.open(os.path.join(out_dir, name), "wb") as f:
		f.setnchannels(1)
		f.setsampwidth(2)
		f.setframerate(11025)
		f.writeframes(struct.pack("<%dh" % len(chosen), *chosen))


record("doppler_off.wav", 0.0, 1.0)
record("doppler_on.wav", 1.0, 1.0)
record("doppler_far.wav", 1.0, 0.25)
